-- Prisma's generator does not emit a DB-level DEFAULT for @updatedAt columns
-- (it treats updatedAt as client-managed), so the auto-generated migration
-- originally left these columns without a default, which fails against the
-- already-populated dev tables. Every `"updatedAt" ... NOT NULL` line below
-- has been hand-edited to add `DEFAULT CURRENT_TIMESTAMP`, matching the
-- `createdAt` columns: existing rows get backfilled to "now", and all future
-- writes still get updatedAt set by Prisma's @updatedAt on every mutation.
-- AlterTable
ALTER TABLE "AcademicYear" ADD COLUMN     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AlterTable
ALTER TABLE "Assignment" ADD COLUMN     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AlterTable
ALTER TABLE "AssignmentStatus" ADD COLUMN     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

